 3	declare(strict_types=1);
 4	
 5	namespace Application\Bootstrap\Screen;
 6	
 7	use Application\Application;
 8	use Application\AppFactory;
 9	use Application\Bootstrap\BootException;
10	use Application\ConfigSettings\BaseConfigRegistry;
11	use Application_Bootstrap_Screen;
12	use AppUtils\FileHelper;
13	use DBHelper;
14	use DBHelper_OperationTypes;
15	
16	class TestSuiteBootstrap extends Application_Bootstrap_Screen
17	{
18	    // Thrown when system users are missing from the test database; run "composer seed-tests" to seed them.
19	    public const int ERROR_TEST_DB_NOT_SEEDED = 175001;
20	    // Thrown when Application::getSystemUserIDs() returns an empty array (no system users configured).
21	    public const int ERROR_NO_SYSTEM_USERS_CONFIGURED = 175002;
22	    // Thrown when the expected tests root folder does not exist on disk.
23	    public const int ERROR_TESTS_FOLDER_NOT_FOUND = 175003;
24	    // Thrown when one or more required APP_DB_TESTS_* constants are not defined in the test config.
25	    public const int ERROR_TEST_DB_CONSTANTS_MISSING = 175004;
26	
27	    public const array SEED_LOCALES = array('de_DE', 'en_UK');
28	
29	    // These 8 countries cover the framework's test needs without over-seeding.
30	    // Note: 'gb' is the correct ISO 3166-1 alpha-2 code for United Kingdom;
31	    // CountryCollection::filterCode() normalizes 'uk' → 'gb' for legacy lookups.
32	    public const array SEED_COUNTRIES = array(
33	        'de' => 'Germany',
34	        'ca' => 'Canada',
35	        'fr' => 'France',
36	        'it' => 'Italy',
37	        'es' => 'Spain',
38	        'gb' => 'United Kingdom',
39	        'us' => 'United States',
40	        'mx' => 'Mexico',
41	    );
42	
43	    protected function _boot() : void
44	    {
45	        $this->disableAuthentication();
46	        $this->enableScriptMode();
47	
48	        // In seed mode the application environment (session, driver, user
49	        // authentication) is not needed and must not be started because the
50	        // known_users table may be empty at this point.
51	        if(!defined('APP_SEED_MODE'))
52	        {
53	            $this->createEnvironment();
54	        }
55	
56	        if (!defined('APP_TESTS_RUNNING')) {
57	            define('APP_TESTS_RUNNING', true);
58	        }
59	
60	        $this->configureDatabase();
61	        $this->registerTransactionCleanupHandler();
62	
63	        if(!defined('APP_SEED_MODE'))
64	        {
65	            $this->configurePaths();
66	            $this->configureUsers();
67	        }
68	    }
69	
70	    private function configureDatabase(): void
71	    {
72	        $requiredConstants = array(
73	            'APP_DB_TESTS_NAME',
74	            'APP_DB_TESTS_USER',
75	            'APP_DB_TESTS_PASSWORD',
76	            'APP_DB_TESTS_HOST'
77	        );
78	
79	        $missing = array();
80	        foreach($requiredConstants as $name)
81	        {
82	            if(!defined($name))
83	            {
84	                $missing[] = $name;
85	            }
86	        }
87	
88	        if(!empty($missing))
89	        {
90	            throw new BootException(
91	                'Test database constants not configured.',
92	                sprintf(
93	                    'The following required constants are not defined: [%s]. ' .
94	                    'Ensure they are set in the test configuration file.',
95	                    implode(', ', $missing)
96	                ),
97	                self::ERROR_TEST_DB_CONSTANTS_MISSING
98	            );
99	        }

101	        $port = 0;
102	
103	        if (defined('APP_DB_TESTS_PORT')) {
104	            $port = (int)APP_DB_TESTS_PORT;
105	        }
106	
107	        DBHelper::registerDB(
108	            'tests',
109	            APP_DB_TESTS_NAME,
110	            APP_DB_TESTS_USER,
111	            APP_DB_TESTS_PASSWORD,
112	            APP_DB_TESTS_HOST,
113	            $port
114	        );
115	
116	        DBHelper::selectDB('tests');
117	    }
118	
119	    private function configureUsers(): void
120	    {
121	        $users = AppFactory::createUsers();
122	        $systemUserIDs = Application::getSystemUserIDs();
123	
124	        if(empty($systemUserIDs))
125	        {
126	            throw new BootException(
127	                'No system users configured.',
128	                'Application::getSystemUserIDs() returned an empty array. ' .
129	                'At least one system user ID must be configured for the test environment.',
130	                self::ERROR_NO_SYSTEM_USERS_CONFIGURED
131	            );
132	        }
133	
134	        $missingIDs = array();
135	
136	        foreach($systemUserIDs as $id)
137	        {
138	            if(!$users->idExists($id))
139	            {
140	                $missingIDs[] = $id;
141	            }
142	        }
143	
144	        if(!empty($missingIDs))
145	        {
146	            throw new BootException(
147	                'Test database not seeded: system user(s) missing.',
148	                sprintf(
149	                    'The following system user IDs are missing from the test database: [%s]. '.
150	                    'Run "composer seed-tests" to initialize the test environment.',
151	                    implode(', ', $missingIDs)
152	                ),
153	                self::ERROR_TEST_DB_NOT_SEEDED
154	            );
155	        }
156	
157	        $this->log('System users verified.');
158	    }
159	
160	    /**
161	     * Seeds system users into the test database within a transaction.
162	     *
163	     * Starts a database transaction, runs the {@see InitSystemUsers} installer
164	     * task, and commits on success. On any failure the transaction is rolled
165	     * back via {@see DBHelper::rollbackConditional()} and the original
166	     * throwable is re-thrown.
167	     *
168	     * Invoke this method via the Composer helper before running the test suite:
169	     *
170	     * <pre>composer seed-tests</pre>
171	     *
172	     * @see ComposerScripts::seedTests()
173	     * @return void
174	     * @throws \Application_Exception If the {@see InitSystemUsers} task ID is
175	     *                                not found in the installer task registry.
176	     * @throws \Throwable             Re-throws any exception or error raised
177	     *                                during task execution after rolling back
178	     *                                the transaction.
179	     */
180	    public static function seedSystemUsers(): void
181	    {
182	        DBHelper::startTransaction();
183	
184	        try
185	        {
186	            Application::createInstaller()
187	                ->getTaskByID('InitSystemUsers')
188	                ->process();
189	
190	            DBHelper::commitTransaction();
191	        }
192	        catch(\Throwable $e)
193	        {
194	            DBHelper::rollbackConditional();
195	            throw $e;
196	        }
197	    }
198	
199	    /**
200	     * Seeds the required application and content locales into the test database.
201	     *
202	     * Inserts the locales defined in {@see self::SEED_LOCALES} into both
203	     * <code>locales_application</code> and <code>locales_content</code> tables
204	     * via {@see DBHelper::insertDynamic()}. Each insert is guarded by a
205	     * {@see DBHelper::recordExists()} check so the method is safe to call even
206	     * on an already-seeded database (e.g. on a partial re-run). Operations are
207	     * wrapped in a transaction.
208	     *
209	     * @return void
210	     * @throws \Throwable Re-throws any exception after rolling back.
211	     */
212	    public static function seedLocales(): void
213	    {
214	        DBHelper::startTransaction();
215	
216	        try
217	        {
218	            foreach(self::SEED_LOCALES as $name)
219	            {
220	                if(!DBHelper::recordExists('locales_application', array('locale_name' => $name)))
221	                {
222	                    DBHelper::insertDynamic('locales_application', array('locale_name' => $name));
223	                }
224	
225	                if(!DBHelper::recordExists('locales_content', array('locale_name' => $name)))
226	                {
227	                    DBHelper::insertDynamic('locales_content', array('locale_name' => $name));
228	                }
229	            }
230	
231	            DBHelper::commitTransaction();
232	        }
233	        catch(\Throwable $e)
234	        {
235	            DBHelper::rollbackConditional();
236	            throw $e;
237	        }
238	    }
239	
240	    /**
241	     * Truncates all base tables in the test database.
242	     *
243	     * Disables FK checks before truncating and re-enables them in a
244	     * <code>finally</code> block so they are guaranteed to be restored even if
245	     * a truncation fails mid-loop. This method does not use a transaction
246	     * because MySQL TRUNCATE is a DDL statement that auto-commits.
247	     *
248	     * @return void
249	     * @throws \DBHelper_Exception
250	     */

251	    public static function truncateAllTables(): void
252	    {
253	        DBHelper::execute(DBHelper_OperationTypes::TYPE_UPDATE, 'SET FOREIGN_KEY_CHECKS=0');
254	
255	        try
256	        {
257	            $entries = DBHelper::fetchAll("SHOW FULL TABLES WHERE Table_type = 'BASE TABLE'");
258	
259	            foreach($entries as $entry)
260	            {
261	                DBHelper::truncate($entry[key($entry)]);
262	            }
263	        }
264	        finally
265	        {
266	            DBHelper::execute(DBHelper_OperationTypes::TYPE_UPDATE, 'SET FOREIGN_KEY_CHECKS=1');
267	        }
268	    }
269	
270	    /**
271	     * Seeds the required countries into the test database.
272	     *
273	     * Creates the ZZ invariant country and the countries listed in
274	     * {@see self::SEED_COUNTRIES}. Each regular country insert is guarded by
275	     * an {@see Application_Countries::isoExists()} check so the method is safe
276	     * to call even without a preceding {@see truncateAllTables()} (e.g. on a
277	     * partial re-run). Operations are wrapped in a transaction.
278	     *
279	     * @return void
280	     * @throws \Throwable Re-throws any exception after rolling back.
281	     */
282	    public static function seedCountries(): void
283	    {
284	        DBHelper::startTransaction();
285	
286	        try
287	        {
288	            $countries = AppFactory::createCountries();
289	
290	            $countries->createInvariantCountry();
291	
292	            foreach(self::SEED_COUNTRIES as $iso => $label)
293	            {
294	                if(!$countries->isoExists($iso))
295	                {
296	                    $countries->createNewCountry($iso, $label);
297	                }
298	            }
299	
300	            DBHelper::commitTransaction();
301	        }
302	        catch(\Throwable $e)
303	        {
304	            DBHelper::rollbackConditional();
305	            throw $e;
306	        }
307	    }
308	
309	    /**
310	     * Registers a PHP shutdown handler to roll back any open transaction if
311	     * the process exits unexpectedly. Called before {@see configurePaths()} so
312	     * that even a fatal error during path setup cannot leave the database in a
313	     * partially-modified state.
314	     */
315	    private function registerTransactionCleanupHandler(): void
316	    {
317	        register_shutdown_function(static function(): void {
318	            DBHelper::rollbackConditional();
319	        });
320	    }
321	
322	    private function configurePaths(): void
323	    {
324	        $testsRoot = APP_ROOT . '/tests';
325	
326	        if (BaseConfigRegistry::areUnitTestsRunning()) {
327	            $testsRoot = APP_ROOT;
328	        }
329	
330	        if (!is_dir($testsRoot)) {
331	            throw new BootException(
332	                'Cannot run tests: tests folder not found.',
333	                sprintf(
334	                    'The expected tests folder [%s] does not exist.',
335	                    $testsRoot
336	                ),
337	                self::ERROR_TESTS_FOLDER_NOT_FOUND
338	            );
339	        }
340	
341	        define('TESTS_ASSETS_FOLDER', TESTS_ROOT . '/assets');
342	        define('TESTS_CLASSES_FOLDER', TESTS_ASSETS_FOLDER . '/classes');
343	
344	        if (is_dir(TESTS_CLASSES_FOLDER)) {
345	            $names = FileHelper::createFileFinder(TESTS_CLASSES_FOLDER)
346	                ->getPHPClassNames();
347	
348	            // load all classes that may be needed for the tests to run.
349	            foreach ($names as $name) {
350	                require_once TESTS_CLASSES_FOLDER . '/' . $name . '.php';
351	            }
352	        }
353	    }
354	
355	    public function getDispatcher() : string
356	    {
357	        return 'bootstrap.php';
358	    }
359	}

